WITH enriched AS (SELECT *, LAG(rating) OVER (PARTITION BY country, city ORDER BY rating, id) AS prev_rating, LEAD(rating) OVER (PARTITION BY country, city ORDER BY rating, id) AS next_rating, ROW_NUMBER() OVER (PARTITION BY country, city ORDER BY rating, id) AS row_seq, MIN(rating) OVER (PARTITION BY country, city) AS country_min_rating FROM suppliers) SELECT country, SUM(prev_rating) FILTER (WHERE city = 'New York') AS new_york_total_prev_rating, SUM(country_min_rating) FILTER (WHERE country = 'JP') AS jp_total_country_min_rating, COUNT(*) AS cnt FROM enriched GROUP BY country HAVING COUNT(*) > 1;
